            assert_eq!(url.fragment(), None);
            assert!(pins(url.host_str().unwrap(), &["13.33.88.1".parse().unwrap()]).is_ok());
        }
        for url in [
            "http://hf.co/x",
            "https://example.com/x",
            "https://hf.co.evil/x",
            "https://u:p@hf.co/x",
            "https://hf.co:444/x",
        ] {
            assert!(trusted(url).is_err());
        }
        for ip in [
            "169.254.169.254",
            "127.0.0.1",
            "10.0.0.1",
            "100.64.0.1",
            "192.0.2.1",
            "::1",
            "fc00::1",
            "::ffff:127.0.0.1",
            "2001:db8::1",
        ] {
            assert!(
                pins(
                    "hf.co",
                    &["13.33.88.1".parse().unwrap(), ip.parse().unwrap()]
                )
                .is_err(),
                "{ip}"
            );
        }
