fn pressure_requires_measured_baseline_complete_success_and_all_gains() {
    let contract = fixture_contract("agentic-eviction-pressure");
    let mut rows = vec![
        row(
            Version::Old,
            64,
            [92061.5, 14.0, 30000.0, 38646.5, 41132.9, 12.02],
        ),
        row(
