            64,
            [66735.5, 10.0, 20000.0, 27901.1, 30328.4, 16.26],
        ),
    ];
    assert!(acceptance::evaluate(&rows, &contract).unwrap().passed);
    rows[0].suffix_prefill_tokens_median = Some(49999.0);
